INSERT INTO type_fiche (tyf_code, tyf_libelle, tyf_table, tyf_cle, tyf_colonne_proprietes, tyf_definition) VALUES
 ('salarie', 'Salarié', 'salarie', 'sal_id', 'sal_proprietes', '{"libelle":"Salarié","titre":"[prenom] [nom]","chrono":{"champ":"code","prefixe":"S","format":"{P}{N:5}","raz":"J"},"sous_titre":"[matricule] · [poste]","sections":[{"code":"entreprise","titre":"Entreprise","groupes":[{"titre":"Identité","champs":["matricule","code","matricule_paie","nom","prenom","ind_id"]},{"titre":"Emploi","champs":["agence","service","poste","qualification","type_mo","statut","date_entree","date_sortie","usage"]},{"titre":"Coordonnées professionnelles","champs":["email","telephone"]},{"titre":"Rémunération","champs":["salaire_brut","heures_mois","cout_horaire"]},{"titre":"Horaires","champs":["cal_id"]},{"titre":"Note professionnelle","champs":["commentaire"],"largeur":"plein"}]},{"code":"prive","titre":"Privé (RGPD)","groupes":[{"titre":"État civil","champs":["date_naissance","num_secu"]},{"titre":"Coordonnées personnelles","champs":["adresse","code_postal","ville","telephone_perso","email_perso"]},{"titre":"Personne à prévenir","champs":["contact_nom","contact_telephone"]},{"titre":"Note personnelle","champs":["note_perso"],"largeur":"plein"}]}],"champs":[{"code":"matricule","libelle":"Matricule","colonne":"sal_matricule","type":"texte","obligatoire":true,"longueur":10,"saisie":"creation","non_copie":true,"aide":"Identifiant unique, saisi à la création"},{"code":"code","libelle":"Code","colonne":"sal_code","type":"texte","longueur":20,"non_copie":true,"aide":"Code court du salarié : recherche rapide, homonymes"},{"code":"matricule_paie","libelle":"Matricule de paie","colonne":"sal_matricule_paie","type":"texte","longueur":30,"non_copie":true,"aide":"Matricule du logiciel de paie (export des variables de paie) ; vide : le matricule"},{"code":"nom","libelle":"Nom","colonne":"sal_nom","type":"texte","obligatoire":true,"longueur":60},{"code":"ind_id","libelle":"Individu (annuaire)","colonne":"sal_ind_id","type":"nombre","reference":"individu","non_copie":true,"aide":"Fiche de l''individu dans l''annuaire : identité et coordonnées partagées avec les autres modules"},{"code":"prenom","libelle":"Prénom","colonne":"sal_prenom","type":"texte","obligatoire":true,"longueur":60},{"code":"date_naissance","libelle":"Date de naissance","colonne":"sal_date_naissance","type":"date","confidentiel":true},{"code":"num_secu","libelle":"N° de sécurité sociale","colonne":"sal_num_secu","type":"texte","confidentiel":true,"non_copie":true,"longueur":21,"format":"regex:^[12] ?[0-9]{2} ?[0-9]{2} ?[0-9]{2} ?[0-9]{3} ?[0-9]{3} ?[0-9]{2}$","aide":"13 chiffres + clé (espaces acceptés)"},{"code":"service","libelle":"Service","colonne":"sal_service","type":"liste","obligatoire":true,"requete":"SELECT s.srv_code, CASE WHEN p.srv_id IS NULL THEN s.srv_libelle ELSE p.srv_libelle || '' › '' || s.srv_libelle END FROM service s LEFT JOIN service p ON p.srv_id = s.srv_parent_id WHERE s.srv_actif ORDER BY coalesce(p.srv_ordre, s.srv_ordre), coalesce(p.srv_code, s.srv_code), s.srv_parent_id NULLS FIRST, s.srv_ordre","aide":"Service principal (planning, pointage, exécution) ; les autres appartenances se gèrent dans Paramètres › Services"},{"code":"poste","libelle":"Poste","colonne":"sal_poste","type":"texte","longueur":60},{"code":"agence","libelle":"Agence","colonne":"sal_agence","type":"liste","options":[{"valeur":"Lyon","libelle":"Lyon"},{"valeur":"Saint-Étienne","libelle":"Saint-Étienne"},{"valeur":"Grenoble","libelle":"Grenoble"},{"valeur":"Bourg-en-Bresse","libelle":"Bourg-en-Bresse"}]},{"code":"type_mo","libelle":"Type de main-d''œuvre","colonne":"sal_type_mo","type":"liste","options":[{"valeur":"OUVRIER","libelle":"Ouvrier"},{"valeur":"ETAM","libelle":"ETAM"},{"valeur":"CADRE","libelle":"Ingénieur et cadre"}],"aide":"Catégorie conventionnelle BTP"},{"code":"statut","libelle":"Contrat","colonne":"sal_statut","type":"liste","options":[{"valeur":"CDI","libelle":"CDI"},{"valeur":"CDD","libelle":"CDD"},{"valeur":"INTERIM","libelle":"Intérim"}]},{"code":"date_entree","libelle":"Date d''entrée","colonne":"sal_date_entree","type":"date"},{"code":"actif","libelle":"Actif","colonne":"sal_actif","type":"booleen","obligatoire":true,"defaut":true},{"code":"usage","libelle":"Utilisation","colonne":"sal_usage","type":"liste","obligatoire":true,"defaut":"A","options":[{"valeur":"A","libelle":"En service"},{"valeur":"N","libelle":"Ne plus utiliser"},{"valeur":"S","libelle":"En sommeil"}],"aide":"Ne plus utiliser : les documents en cours se terminent, plus de nouveau choix ; en sommeil : masquée par défaut dans les listes"},{"code":"email","libelle":"E-mail professionnel","colonne":"sal_email","type":"texte","longueur":100,"format":"email","non_copie":true},{"code":"telephone","libelle":"Téléphone professionnel","colonne":"sal_telephone","type":"texte","longueur":20,"format":"telephone"},{"code":"adresse","libelle":"Adresse","colonne":"sal_adresse","type":"zone","longueur":200,"confidentiel":true,"largeur":"plein"},{"code":"code_postal","libelle":"Code postal","colonne":"sal_code_postal","type":"texte","longueur":5,"format":"code_postal","confidentiel":true},{"code":"ville","libelle":"Ville","colonne":"sal_ville","type":"texte","longueur":60,"confidentiel":true},{"code":"telephone_perso","libelle":"Téléphone personnel","colonne":"sal_telephone_perso","type":"texte","longueur":20,"format":"telephone","confidentiel":true},{"code":"email_perso","libelle":"E-mail personnel","colonne":"sal_email_perso","type":"texte","longueur":100,"format":"email","confidentiel":true,"non_copie":true},{"code":"contact_nom","libelle":"Nom et lien","colonne":"sal_contact_nom","type":"texte","longueur":100,"confidentiel":true,"aide":"Ex. Marie Martin (conjointe)"},{"code":"contact_telephone","libelle":"Téléphone","colonne":"sal_contact_telephone","type":"texte","longueur":20,"format":"telephone","confidentiel":true},{"code":"note_perso","libelle":"Note personnelle","colonne":"sal_note_perso","type":"zone","confidentiel":true},{"code":"salaire_brut","libelle":"Salaire brut mensuel","colonne":"sal_salaire","type":"nombre","confidentiel":true,"format":"99999.99"},{"code":"heures_mois","libelle":"Heures mensuelles","colonne":"sal_heures_mois","type":"nombre","format":"999.99","defaut":151.67},{"code":"commentaire","libelle":"Note professionnelle","colonne":"sal_commentaire","type":"zone"},{"code":"qualification","libelle":"Qualification","colonne":"sal_qualification","type":"texte","longueur":60,"aide":"Ex. N3P2 (convention collective), compagnon professionnel"},{"code":"date_sortie","libelle":"Date de sortie","colonne":"sal_date_sortie","type":"date","non_copie":true,"aide":"Le compte de connexion est désactivé quand le salarié n''est plus actif"},{"code":"cal_id","libelle":"Calendrier de travail","colonne":"sal_cal_id","type":"liste","requete":"SELECT cal_id, cal_libelle FROM calendrier WHERE cal_actif ORDER BY cal_defaut DESC, cal_code","aide":"Vide : calendrier du service principal, sinon le calendrier par défaut"},{"code":"cout_horaire","libelle":"Coût horaire chargé","colonne":"sal_cout_horaire","type":"nombre","confidentiel":true,"format":"9999.99","aide":"Vide : estimé depuis le salaire (× 1,45 / heures mensuelles)"}]}'::jsonb),
 ('materiel', 'Matériel', 'materiel', 'mat_id', 'mat_proprietes', '{"libelle":"Matériel","titre":"[designation]","chrono":{"champ":"code","prefixe":"MAT","format":"{P}{N:5}","raz":"J"},"sous_titre":"[code] · [marque] [modele]","sections":[{"code":"informations","titre":"Informations","groupes":[{"titre":"Identification","champs":["code","designation","famille","marque","modele","numero_serie","immatriculation","energie","usage"]},{"titre":"Dates","champs":["date_entree","date_mise_service","fin_garantie","date_sortie"]},{"titre":"Poids et dimensions","champs":["poids","longueur","largeur","hauteur"]},{"titre":"Location","champs":["loueur_id","location_ent_id","fin_location"]},{"titre":"Exploitation","champs":["etat","chantier","compteurs","heures_utilisation","kilometres","controle_ok"]},{"titre":"Planification","champs":["mode","quantite","unite","srv_id","cal_id"]},{"titre":"Achat","champs":["valeur_achat","date_achat"]},{"titre":"Observations","champs":["observations"],"largeur":"plein"}]}],"champs":[{"code":"code","libelle":"Code","colonne":"mat_code","type":"texte","obligatoire":true,"longueur":10,"non_copie":true},{"code":"designation","libelle":"Désignation","colonne":"mat_designation","type":"texte","obligatoire":true,"longueur":100,"largeur":"plein"},{"code":"famille","libelle":"Type","colonne":"mat_famille","type":"liste","obligatoire":true,"requete":"SELECT v.lva_code, CASE WHEN p.lva_code IS NULL THEN v.lva_libelle ELSE p.lva_libelle || '' › '' || v.lva_libelle END FROM liste_valeur v LEFT JOIN liste_valeur p ON p.lva_liste = v.lva_liste AND p.lva_code = v.lva_parent WHERE v.lva_liste = ''TYPE_MATERIEL'' AND v.lva_actif ORDER BY coalesce(p.lva_ordre, v.lva_ordre), coalesce(p.lva_code, v.lva_code), v.lva_parent NULLS FIRST, v.lva_ordre","aide":"Types de matériel regroupés (Paramètres › Référentiels communs)"},{"code":"marque","libelle":"Marque","colonne":"mat_marque","type":"texte","longueur":60},{"code":"numero_serie","libelle":"N° de série","colonne":"mat_numero_serie","type":"texte","longueur":40,"non_copie":true},{"code":"etat","libelle":"État","colonne":"mat_etat","type":"liste","obligatoire":true,"defaut":"DISPO","options":[{"valeur":"DISPO","libelle":"Disponible"},{"valeur":"CHANTIER","libelle":"En chantier"},{"valeur":"PANNE","libelle":"En panne"},{"valeur":"REBUT","libelle":"Rebut"}]},{"code":"chantier","libelle":"Chantier","colonne":"mat_chantier","type":"texte","longueur":100},{"code":"heures_utilisation","libelle":"Heures d''utilisation","colonne":"mat_heures","type":"nombre","lecture_seule":true,"format":"99999","aide":"Dernier relevé du compteur (onglet Compteurs)"},{"code":"controle_ok","libelle":"Contrôle réglementaire à jour","colonne":"mat_controle_ok","type":"booleen","defaut":false},{"code":"valeur_achat","libelle":"Valeur d''achat","colonne":"mat_valeur_achat","type":"nombre","format":"9999999.99"},{"code":"date_achat","libelle":"Date d''achat","colonne":"mat_date_achat","type":"date"},{"code":"observations","libelle":"Observations","colonne":"mat_observations","type":"zone"},{"code":"usage","libelle":"Utilisation","colonne":"mat_usage","type":"liste","obligatoire":true,"defaut":"A","options":[{"valeur":"A","libelle":"En service"},{"valeur":"N","libelle":"Ne plus utiliser"},{"valeur":"S","libelle":"En sommeil"}],"aide":"Ne plus utiliser : les documents en cours se terminent, plus de nouveau choix ; en sommeil : masquée par défaut dans les listes"},{"code":"mode","libelle":"Gestion","colonne":"mat_mode","type":"liste","obligatoire":true,"defaut":"IDENTIFIE","options":[{"valeur":"IDENTIFIE","libelle":"Identifié (un engin)"},{"valeur":"NOMBRE","libelle":"Par nombre (stock)"}]},{"code":"quantite","libelle":"Quantité disponible","colonne":"mat_quantite","type":"nombre","obligatoire":true,"defaut":1,"format":"999999.999","aide":"Matériel par nombre : le planning avertit au-delà"},{"code":"unite","libelle":"Unité","colonne":"mat_unite","type":"texte","longueur":10},{"code":"cal_id","libelle":"Calendrier","colonne":"mat_cal_id","type":"liste","requete":"SELECT cal_id, cal_libelle FROM calendrier WHERE cal_actif ORDER BY cal_defaut DESC, cal_code","aide":"Vide : calendrier du service"},{"code":"modele","libelle":"Modèle","colonne":"mat_modele","type":"texte","longueur":60},{"code":"immatriculation","libelle":"Immatriculation","colonne":"mat_immatriculation","type":"texte","longueur":20,"non_copie":true,"aide":"Unique : un véhicule immatriculé ou un EPI marqué"},{"code":"energie","libelle":"Énergie","colonne":"mat_energie","type":"liste","requete":"SELECT lva_code, lva_libelle FROM liste_valeur WHERE lva_liste = ''ENERGIE'' AND lva_actif ORDER BY lva_ordre, lva_code"},{"code":"compteurs","libelle":"Compteurs","colonne":"mat_compteurs","type":"liste","obligatoire":true,"defaut":"H","options":[{"valeur":"H","libelle":"Heures"},{"valeur":"KM","libelle":"Kilomètres"},{"valeur":"H_KM","libelle":"Heures et kilomètres"},{"valeur":"AUCUN","libelle":"Aucun"}]},{"code":"kilometres","libelle":"Kilométrage","colonne":"mat_kilometres","type":"nombre","lecture_seule":true,"format":"9999999","aide":"Dernier relevé du compteur (onglet Compteurs)"},{"code":"date_entree","libelle":"Date d''entrée","colonne":"mat_date_entree","type":"date"},{"code":"date_mise_service","libelle":"Mise en service","colonne":"mat_date_mise_service","type":"date"},{"code":"fin_garantie","libelle":"Fin de garantie","colonne":"mat_fin_garantie","type":"date"},{"code":"date_sortie","libelle":"Date de sortie","colonne":"mat_date_sortie","type":"date","non_copie":true},{"code":"poids","libelle":"Poids (kg)","colonne":"mat_poids","type":"nombre","format":"999999999.999"},{"code":"longueur","libelle":"Longueur (m)","colonne":"mat_longueur","type":"nombre","format":"9999999.999"},{"code":"largeur","libelle":"Largeur (m)","colonne":"mat_largeur","type":"nombre","format":"9999999.999"},{"code":"hauteur","libelle":"Hauteur (m)","colonne":"mat_hauteur","type":"nombre","format":"9999999.999"},{"code":"loueur_id","libelle":"Loueur","colonne":"mat_loueur_id","type":"liste","requete":"SELECT per_id, per_raison_sociale || coalesce('' ('' || per_code || '')'', '''') FROM personne WHERE per_actif AND (per_casquettes ? ''LOUEUR'' OR per_casquettes ? ''FOURNISSEUR'') ORDER BY per_raison_sociale","aide":"Matériel loué : le loueur (relation Loueur ou Fournisseur de l''annuaire)"},{"code":"location_ent_id","libelle":"Commande de location","colonne":"mat_location_ent_id","type":"liste","requete":"SELECT d.ent_id, coalesce(d.ent_numero, ''Brouillon'') || '' – '' || coalesce(d.ent_objet, '''') FROM document d JOIN type_document t ON t.tyd_id = d.ent_tyd_id WHERE t.tyd_code = ''A_COMMANDE'' AND d.ent_is_reference ORDER BY d.ent_id DESC"},{"code":"fin_location","libelle":"Fin de location","colonne":"mat_fin_location","type":"date","non_copie":true},{"code":"srv_id","libelle":"Service","colonne":"mat_srv_id","type":"liste","requete":"SELECT srv_id, srv_libelle FROM service WHERE srv_actif ORDER BY srv_ordre, srv_code","aide":"Service qui planifie ce matériel"}]}'::jsonb),
 ('element', 'Élément', 'element', 'ele_id', 'ele_proprietes', '{"libelle":"Élément de bibliothèque","titre":"[code] – [libelle]","chrono":{"champ":"code","prefixe":"ELE","format":"{P}{N:6}","raz":"J","portee":"bib_id"},"sous_titre":"[bib_code] · [famille]","sections":[{"code":"article","titre":"Article","groupes":[{"titre":"Identification","champs":["bib_id","code","type","usage","code_barre"]},{"titre":"Classement","champs":["fam_id","nat_id","gestion","delai_livraison"]},{"titre":"Libellé","champs":["libelle_html"],"largeur":"plein"},{"code":"recherche","titre":"Recherche","champs":["mots_cles"],"largeur":"plein"},{"code":"description","titre":"Description technique","champs":["description_html"],"largeur":"plein"},{"code":"techniques","titre":"Données techniques (par unité de stock)","champs":["poids","surface","surface_peinture","volume","hauteur","largeur","epaisseur","longueur"],"largeur":"plein"},{"code":"isolation","titre":"Isolation","champs":["isolant_epaisseur","isolant_lambda","isolant_r","isolant_u"]},{"code":"poste","titre":"Poste de pied","champs":["pied_niveau","pied_mode","pied_base","pied_sens","pied_valeur","pied_retenue","cpt_code","tva_code"]}]}],"champs":[{"code":"bib_id","libelle":"Bibliothèque","colonne":"ele_bib_id","type":"nombre","obligatoire":true,"saisie":"creation","reference":"bibliotheque"},{"code":"code","libelle":"Code","colonne":"ele_code","type":"texte","obligatoire":true,"longueur":30,"non_copie":true,"format":"regex:^[^:\\s][^:]*$","aide":"Unique dans la bibliothèque ; sans « : » (réservé à l''appel BIB:CODE)"},{"code":"type","libelle":"Type","colonne":"ele_type","type":"liste","obligatoire":true,"defaut":"ARTICLE","saisie":"creation","options":[{"valeur":"ARTICLE","libelle":"Article"},{"valeur":"OUVRAGE","libelle":"Ouvrage"},{"valeur":"ENSEMBLE","libelle":"Ensemble"},{"valeur":"POSTE_PIED","libelle":"Poste de pied"},{"valeur":"TEXTE","libelle":"Texte"}],"aide":"Ensemble : structure de lignes réutilisable (lignes vendues, options, variantes) paramétrée par sa tranche ; poste de pied : retenue, compte prorata, remise… pour le pied des documents ; texte : ligne de texte ou texte de l''édition (introduction, conclusion)"},{"code":"actif","libelle":"Actif","colonne":"ele_actif","type":"booleen","obligatoire":true,"defaut":true},{"code":"usage","libelle":"Utilisation","colonne":"ele_usage","type":"liste","obligatoire":true,"defaut":"A","options":[{"valeur":"A","libelle":"En service"},{"valeur":"N","libelle":"Ne plus utiliser"},{"valeur":"S","libelle":"En sommeil"}],"aide":"Ne plus utiliser : les documents en cours se terminent, plus de nouveau choix ; en sommeil : masquée par défaut dans les listes"},{"code":"libelle_html","libelle":"Libellé","colonne":"ele_libelle_html","type":"html","obligatoire":true},{"code":"libelle","libelle":"Libellé (texte brut)","colonne":"ele_libelle","type":"texte","lecture_seule":true},{"code":"fam_id","libelle":"Famille","colonne":"ele_fam_id","type":"nombre","reference":"famille"},{"code":"nat_id","libelle":"Nature","colonne":"ele_nat_id","type":"nombre","reference":"nature"},{"code":"gestion","libelle":"Type de gestion","colonne":"ele_gestion","type":"liste","obligatoire":true,"defaut":"NON_GERE","options":[{"valeur":"STOCK","libelle":"Stock"},{"valeur":"ACHAT","libelle":"Achat"},{"valeur":"SOUS_TRAITANCE","libelle":"Sous-traitance"},{"valeur":"NON_GERE","libelle":"Non géré"}]},{"code":"unite_stock","libelle":"Unité de stock","colonne":"ele_unt_stock","type":"texte","obligatoire":true,"longueur":10},{"code":"unite_achat","libelle":"Unité d''achat","colonne":"ele_unt_achat","type":"texte","longueur":10},{"code":"unite_vente","libelle":"Unité de vente","colonne":"ele_unt_vente","type":"texte","longueur":10},{"code":"unites","libelle":"Correspondances d''unités","colonne":"ele_unites","type":"json"},{"code":"scenario_pa","libelle":"Scénario de prix d''achat","colonne":"ele_scenario_pa","type":"liste","obligatoire":true,"defaut":"FIXE","options":[{"valeur":"FIXE","libelle":"FIXE"},{"valeur":"FOURNISSEUR_PRINCIPAL","libelle":"FOURNISSEUR_PRINCIPAL"},{"valeur":"DERNIER_PA","libelle":"DERNIER_PA"},{"valeur":"MEILLEUR_MIN","libelle":"MEILLEUR_MIN"},{"valeur":"MEILLEUR_MAX","libelle":"MEILLEUR_MAX"},{"valeur":"PMP","libelle":"PMP"}]},{"code":"scenarios","libelle":"Scénarios autorisés","colonne":"ele_scenarios","type":"json"},{"code":"pa_fixe","libelle":"Prix fixe","colonne":"ele_pa_fixe","type":"nombre"},{"code":"dernier_pa","libelle":"Dernier prix d''achat","colonne":"ele_dernier_pa","type":"nombre"},{"code":"pmp","libelle":"Prix moyen pondéré","colonne":"ele_pmp","type":"nombre"},{"code":"pa","libelle":"Prix d''achat","colonne":"ele_pa","type":"nombre","lecture_seule":true},{"code":"coef_fg","libelle":"Coef. frais généraux","colonne":"ele_coef_fg","type":"nombre","obligatoire":true,"defaut":"1.1","aide":"Imposé, sinon celui de la nature ou global en vigueur"},{"code":"coef_fg_impose","libelle":"Frais généraux imposés","colonne":"ele_coef_fg_impose","type":"booleen","obligatoire":true,"defaut":false},{"code":"coef_benef_impose","libelle":"Bénéfice imposé","colonne":"ele_coef_benef_impose","type":"booleen","obligatoire":true,"defaut":false},{"code":"pr","libelle":"Prix de revient","colonne":"ele_pr","type":"nombre","lecture_seule":true},{"code":"coef_benef","libelle":"Coef. bénéfice","colonne":"ele_coef_benef","type":"nombre","obligatoire":true,"defaut":"1.2"},{"code":"pv","libelle":"Prix de vente","colonne":"ele_pv","type":"nombre"},{"code":"pv_fixe","libelle":"PV fixe","colonne":"ele_pv_fixe","type":"booleen","obligatoire":true,"defaut":false},{"code":"coef_remise","libelle":"Coef. de remise","colonne":"ele_coef_remise","type":"nombre","obligatoire":true,"defaut":"1"},{"code":"pv_net","libelle":"PV net","colonne":"ele_pv_net","type":"nombre","lecture_seule":true},{"code":"composition","libelle":"Composition","colonne":"ele_composition","type":"json"},{"code":"image_ged","libelle":"Image","colonne":"ele_image_ged","type":"nombre"},{"code":"poids","libelle":"Poids (kg)","colonne":"ele_poids","type":"nombre","format":"99999999.999999"},{"code":"surface","libelle":"Surface (m²)","colonne":"ele_surface","type":"nombre","format":"99999999.999999"},{"code":"surface_peinture","libelle":"Surface à peindre (m²)","colonne":"ele_surface_peinture","type":"nombre","format":"99999999.999999"},{"code":"volume","libelle":"Volume (m³)","colonne":"ele_volume","type":"nombre","format":"99999999.999999"},{"code":"hauteur","libelle":"Hauteur (mm)","colonne":"ele_hauteur","type":"nombre","format":"999999999.999"},{"code":"largeur","libelle":"Largeur (mm)","colonne":"ele_largeur","type":"nombre","format":"999999999.999"},{"code":"epaisseur","libelle":"Épaisseur (mm)","colonne":"ele_epaisseur","type":"nombre","format":"999999999.999"},{"code":"longueur","libelle":"Longueur (mm)","colonne":"ele_longueur","type":"nombre","format":"999999999.999","aide":"Longueur de barre, de rouleau… (recopiée en mètres sur la ligne du document)"},{"code":"isolant_epaisseur","libelle":"Épaisseur (mm)","colonne":null,"type":"nombre","lecture_seule":true,"aide":"Épaisseur des données techniques"},{"code":"isolant_lambda","libelle":"Conductivité λ (W/m.K)","colonne":"ele_isolant_lambda","type":"nombre","format":"99999.99999"},{"code":"isolant_r","libelle":"Résistance thermique R (m².K/W)","colonne":"ele_isolant_r","type":"nombre","format":"999999.9999","aide":"R = épaisseur (m) / λ"},{"code":"isolant_u","libelle":"Coefficient U (W/m².K)","colonne":"ele_isolant_u","type":"nombre","format":"999999.9999","aide":"U ≈ 1 / R (paroi seule)"},{"code":"commentaire_prix","libelle":"Commentaire de la modification de prix","colonne":"ele_commentaire_prix","type":"texte","longueur":500},{"code":"maj_par","libelle":"Modifié par","colonne":"ele_maj_par","type":"texte","lecture_seule":true},{"code":"pied_niveau","libelle":"Niveau","colonne":"ele_pied_niveau","type":"liste","options":[{"valeur":"HT","libelle":"Poste HT (avant TVA)"},{"valeur":"TTC","lib