","type":"nombre","format":"9999","aide":"Délai global de l''élément"}]}'::jsonb),
 ('personne', 'Personne', 'personne', 'per_id', 'per_proprietes', '{"libelle":"Personne","titre":"[raison_sociale]","chrono":{"champ":"code","prefixe":"T","format":"{P}{N:6}","raz":"J"},"sous_titre":"[code]","sections":[{"code":"identite","titre":"Identité","groupes":[{"titre":"Identification","champs":["niveau","raison_sociale","nom_commercial","sigle","code","parent_id","usage","societe_base"]},{"code":"casquettes","titre":"Relations avec nous","champs":["casquettes"],"largeur":"plein"},{"code":"activites","titre":"Activités","champs":["activites"],"largeur":"plein"},{"code":"entreprise","titre":"Entreprise","champs":["pays","siren","siret","tva_intra","identifiant_etranger","naf","forme_juridique","forme_libelle","capital","rcs","date_creation","effectif","etat_administratif","siege","service_public"]},{"titre":"Notes","champs":["commentaire"],"largeur":"plein"}]},{"code":"facturation","titre":"Facturation et règlement","groupes":[{"code":"facturation_electronique","titre":"Facturation électronique","champs":["fe_type","assujetti_tva","fe_format","fe_plateforme","fe_adresse","fe_code_routage","fe_code_service","fe_engagement"]},{"titre":"Règlement","champs":["mode_reglement","delai_paiement","devise","iban","bic"]}]},{"code":"casquettes","titre":"Par relation","groupes":[{"code":"client","titre":"Client","champs":["cli_charge_ind_id","cli_mode_reglement","cli_delai_paiement","cli_compte","cli_collectif","cli_categorie","cli_encours_max","cli_remise"]},{"code":"fournisseur","titre":"Fournisseur","champs":["fou_mode_reglement","fou_delai_paiement","fou_tva_intracom","fou_compte","fou_collectif","fou_numero_client","fou_franco","fou_delai_livraison"]},{"code":"sous_traitant","titre":"Sous-traitant","champs":["st_compte","st_collectif","st_corps_etat","st_qualifications","st_autoliquidation","st_decennale_assureur","st_decennale_police","st_decennale_fin"]},{"code":"interim","titre":"Agence d''intérim","champs":["int_garantie_financiere","int_coefficient"]},{"code":"architecte","titre":"Architecte","champs":["arc_numero_ordre"]},{"code":"controle","titre":"Bureau de contrôle","champs":["bc_agrement","bc_missions"]}]}],"champs":[{"code":"code","libelle":"Code","colonne":"per_code","type":"texte","longueur":20,"non_copie":true,"aide":"Code du tiers : vide à la création = chrono (T000123 par défaut)"},{"code":"niveau","libelle":"Niveau","colonne":"per_niv_code","type":"texte","obligatoire":true,"defaut":"SOCIETE","reference":"niveau"},{"code":"raison_sociale","libelle":"Raison sociale ou nom","colonne":"per_raison_sociale","type":"texte","obligatoire":true,"longueur":150},{"code":"nom_commercial","libelle":"Nom commercial (enseigne)","colonne":"per_nom_commercial","type":"texte","longueur":150},{"code":"sigle","libelle":"Sigle","colonne":"per_sigle","type":"texte","longueur":30},{"code":"parent_id","libelle":"Niveau supérieur","colonne":"per_parent_id","type":"nombre","reference":"personne","aide":"Groupe d''une société, société d''un établissement, d''une agence…"},{"code":"casquettes","libelle":"Relations","colonne":"per_casquettes","type":"json","aide":"Client, fournisseur, sous-traitant… : une personne peut en avoir plusieurs"},{"code":"actif","libelle":"Actif","colonne":"per_actif","type":"booleen","obligatoire":true,"defaut":true},{"code":"usage","libelle":"Utilisation","colonne":"per_usage","type":"liste","obligatoire":true,"defaut":"A","options":[{"valeur":"A","libelle":"En service"},{"valeur":"N","libelle":"Ne plus utiliser"},{"valeur":"S","libelle":"En sommeil"}],"aide":"Ne plus utiliser : les documents en cours se terminent, plus de nouveau choix ; en sommeil : masquée par défaut dans les listes"},{"code":"societe_base","libelle":"Société de cette base","colonne":"per_societe_base","type":"booleen","obligatoire":true,"defaut":false,"non_copie":true,"aide":"Notre société (une seule par base)"},{"code":"pays","libelle":"Pays","colonne":"per_pays","type":"texte","defaut":"FR","longueur":2,"format":"regex:^[A-Za-z]{2}$","aide":"Code ISO à 2 lettres (FR, BE, DE…)"},{"code":"siren","libelle":"SIREN","colonne":"per_siren","type":"texte","longueur":11,"non_copie":true},{"code":"siret","libelle":"SIRET","colonne":"per_siret","type":"texte","longueur":17,"non_copie":true,"aide":"Unique : un établissement n''est enregistré qu''une fois"},{"code":"tva_intra","libelle":"N° de TVA intracommunautaire","colonne":"per_tva_intra","type":"texte","longueur":20,"non_copie":true},{"code":"identifiant_etranger","libelle":"Identifiant hors France","colonne":"per_identifiant_etranger","type":"texte","longueur":40,"non_copie":true,"aide":"N° d''enregistrement national (entreprise étrangère)"},{"code":"naf","libelle":"Code NAF (APE)","colonne":"per_naf","type":"texte","longueur":6},{"code":"forme_juridique","libelle":"Catégorie juridique (code)","colonne":"per_forme_juridique","type":"texte","longueur":10},{"code":"forme_libelle","libelle":"Forme juridique","colonne":"per_forme_libelle","type":"texte","longueur":100},{"code":"capital","libelle":"Capital","colonne":"per_capital","type":"nombre","format":"9999999999999999.99"},{"code":"rcs","libelle":"RCS","colonne":"per_rcs","type":"texte","longueur":60},{"code":"date_creation","libelle":"Date de création","colonne":"per_date_creation","type":"date"},{"code":"effectif","libelle":"Effectif","colonne":"per_effectif","type":"texte","longueur":40},{"code":"etat_administratif","libelle":"État administratif","colonne":"per_etat_administratif","type":"liste","options":[{"valeur":"A","libelle":"Actif"},{"valeur":"F","libelle":"Fermé"}]},{"code":"siege","libelle":"Siège","colonne":"per_siege","type":"booleen"},{"code":"service_public","libelle":"Service public (Chorus Pro)","colonne":"per_service_public","type":"booleen","defaut":false},{"code":"fe_format","libelle":"Format de facture","colonne":"per_fe_format","type":"liste","options":[{"valeur":"FACTURX","libelle":"Factur-X"},{"valeur":"UBL","libelle":"UBL"},{"valeur":"CII","libelle":"CII"}]},{"code":"fe_plateforme","libelle":"Plateforme de réception (PA)","colonne":"per_fe_plateforme","type":"texte","longueur":100,"aide":"Plateforme agréée choisie par le destinataire"},{"code":"fe_adresse","libelle":"Adresse de facturation électronique","colonne":"per_fe_adresse","type":"texte","longueur":150,"aide":"Identifiant de l''annuaire de facturation (SIREN, SIREN_SUFFIXE…)"},{"code":"fe_code_routage","libelle":"Code de routage","colonne":"per_fe_code_routage","type":"texte","longueur":100},{"code":"fe_code_service","libelle":"Code service (Chorus Pro)","colonne":"per_fe_code_service","type":"texte","longueur":100},{"code":"fe_engagement","libelle":"N° d''engagement obligatoire","colonne":"per_fe_engagement","type":"booleen","defaut":false},{"code":"mode_reglement","libelle":"Mode de règlement (par défaut)","colonne":"per_mode_reglement","type":"liste","requete":"SELECT mre_code, mre_libelle FROM mode_reglement WHERE mre_actif ORDER BY mre_ordre, mre_code","aide":"Repli quand le mode du client ou du fournisseur (onglet Par relation) est vide"},{"code":"delai_paiement","libelle":"Délai de paiement (par défaut)","colonne":"per_delai_paiement","type":"liste","requete":"SELECT cpa_code, cpa_libelle FROM condition_paiement WHERE cpa_actif ORDER BY cpa_ordre, cpa_code","aide":"Repli quand le délai du client ou du fournisseur (onglet Par relation) est vide"},{"code":"fe_type","libelle":"Type de tiers (facture électronique)","colonne":"per_fe_type","type":"liste","options":[{"valeur":"B2B","libelle":"Entreprise (B2B)"},{"valeur":"B2C","libelle":"Particulier (B2C)"},{"valeur":"B2G","libelle":"Administration (B2G)"},{"valeur":"INTERNATIONAL","libelle":"International"}]},{"code":"assujetti_tva","libelle":"Assujetti à la TVA","colonne":"per_assujetti_tva","type":"booleen","defaut":true},{"code":"activites","libelle":"Activités","colonne":"per_activites","type":"json","aide":"Plusieurs activités, à deux niveaux (Paramètres › Référentiels communs)"},{"code":"image_ged","libelle":"Logo","colonne":"per_image_ged","type":"nombre","non_copie":true},{"code":"cli_charge_ind_id","libelle":"Chargé d''affaires","colonne":"per_cli_charge_ind_id","type":"liste","requete":"WITH RECURSIVE s AS (SELECT per_id FROM personne WHERE per_societe_base UNION SELECT p.per_id FROM personne p JOIN s ON p.per_parent_id = s.per_id) SELECT DISTINCT ON (i.ind_nom, i.ind_prenom, i.ind_id) i.ind_id, concat_ws('' '', i.ind_prenom, i.ind_nom) FROM individu i JOIN rattachement r ON r.rat_ind_id = i.ind_id AND r.rat_actif JOIN s ON s.per_id = r.rat_per_id WHERE i.ind_actif ORDER BY i.ind_nom, i.ind_prenom, i.ind_id","aide":"Suivi du client : individu de notre société"},{"code":"cli_mode_reglement","libelle":"Mode de règlement (client)","colonne":"per_cli_mode_reglement","type":"liste","requete":"SELECT mre_code, mre_libelle FROM mode_reglement WHERE mre_actif ORDER BY mre_ordre, mre_code"},{"code":"cli_delai_paiement","libelle":"Délai de paiement (client)","colonne":"per_cli_delai_paiement","type":"liste","requete":"SELECT cpa_code, cpa_libelle FROM condition_paiement WHERE cpa_actif ORDER BY cpa_ordre, cpa_code"},{"code":"fou_mode_reglement","libelle":"Mode de règlement (fournisseur)","colonne":"per_fou_mode_reglement","type":"liste","requete":"SELECT mre_code, mre_libelle FROM mode_reglement WHERE mre_actif ORDER BY mre_ordre, mre_code"},{"code":"fou_delai_paiement","libelle":"Délai de paiement (fournisseur)","colonne":"per_fou_delai_paiement","type":"liste","requete":"SELECT cpa_code, cpa_libelle FROM condition_paiement WHERE cpa_actif ORDER BY cpa_ordre, cpa_code"},{"code":"fou_tva_intracom","libelle":"TVA intracommunautaire","colonne":"per_fou_tva_intracom","type":"booleen","defaut":false,"aide":"Fournisseur de l''Union européenne : TVA autoliquidée sur ses factures"},{"code":"devise","libelle":"Devise","colonne":"per_devise","type":"texte","defaut":"EUR","longueur":3},{"code":"iban","libelle":"IBAN","colonne":"per_iban","type":"texte","longueur":42,"non_copie":true},{"code":"bic","libelle":"BIC","colonne":"per_bic","type":"texte","longueur":11},{"code":"commentaire","libelle":"Notes","colonne":"per_commentaire","type":"zone"},{"code":"cli_compte","libelle":"Compte client","colonne":"per_cli_compte","type":"texte","longueur":20,"aide":"Compte auxiliaire (411…)"},{"code":"cli_collectif","libelle":"Collectif client","colonne":"per_cli_collectif","type":"liste","requete":"SELECT cpt_code, cpt_code || '' – '' || cpt_libelle FROM compte_comptable WHERE cpt_actif AND cpt_type = ''COLLECTIF'' ORDER BY cpt_code","aide":"Vide : collectif du type (professionnel ou particulier), module Comptabilité"},{"code":"cli_categorie","libelle":"Catégorie tarifaire","colonne":"per_cli_categorie","type":"texte","longueur":40},{"code":"cli_encours_max","libelle":"Encours autorisé (€)","colonne":"per_cli_encours_max","type":"nombre","format":"999999999999.99"},{"code":"cli_remise","libelle":"Remise habituelle (%)","colonne":"per_cli_remise","type":"nombre","format":"999.999"},{"code":"fou_compte","libelle":"Compte fournisseur","colonne":"per_fou_compte","type":"texte","longueur":20,"aide":"Compte auxiliaire (401…)"},{"code":"fou_collectif","libelle":"Collectif fournisseur","colonne":"per_fou_collectif","type":"liste","requete":"SELECT cpt_code, cpt_code || '' – '' || cpt_libelle FROM compte_comptable WHERE cpt_actif AND cpt_type = ''COLLECTIF'' ORDER BY cpt_code","aide":"Vide : collectif des fournisseurs, module Comptabilité"},{"code":"fou_numero_client","libelle":"Notre n° de client","colonne":"per_fou_numero_client","type":"texte","longueur":40},{"code":"fou_franco","libelle":"Franco de port (€ HT)","colonne":"per_fou_franco","type":"nombre","format":"999999999999.99"},{"code":"fou_delai_livraison","libelle":"Délai de livraison (jours)","colonne":"per_fou_delai_livraison","type":"nombre","format":"9999"},{"code":"st_compte","libelle":"Compte sous-traitant","colonne":"per_st_compte","type":"texte","longueur":20,"aide":"Vide : compte fournisseur ; à saisir pour un compte auxiliaire propre"},{"code":"st_collectif","libelle":"Collectif sous-traitant","colonne":"per_st_collectif","type":"liste","requete":"SELECT cpt_code, cpt_code || '' – '' || cpt_libelle FROM compte_comptable WHERE cpt_actif AND cpt_type = ''COLLECTIF'' ORDER BY cpt_code","aide":"Vide : collectif des sous-traitants, module Comptabilité"},{"code":"st_corps_etat","libelle":"Corps d''état","colonne":"per_st_corps_etat","type":"texte","longueur":100},{"code":"st_qualifications","libelle":"Qualifications (Qualibat…)","colonne":"per_st_qualifications","type":"texte","longueur":200},{"code":"st_autoliquidation","libelle":"Autoliquidation de la TVA","colonne":"per_st_autoliquidation","type":"booleen","defaut":true},{"code":"st_decennale_assureur","libelle":"Assureur décennale","colonne":"per_st_decennale_assureur","type":"texte","longueur":100},{"code":"st_decennale_police","libelle":"N° de police décennale","colonne":"per_st_decennale_police","type":"texte","longueur":50},{"code":"st_decennale_fin","libelle":"Décennale valable jusqu''au","colonne":"per_st_decennale_fin","type":"date"},{"code":"int_garantie_financiere","libelle":"Garantie financière (organisme)","colonne":"per_int_garantie_financiere","type":"texte","longueur":100},{"code":"int_coefficient","libelle":"Coefficient de facturation","colonne":"per_int_coefficient","type":"nombre","format":"9999.9999"},{"code":"arc_numero_ordre","libelle":"N° d''inscription à l''Ordre","colonne":"per_arc_numero_ordre","type":"texte","longueur":30},{"code":"bc_agrement","libelle":"N° d''agrément","colonne":"per_bc_agrement","type":"texte","longueur":50},{"code":"bc_missions","libelle":"Missions (L, SEI, PS…)","colonne":"per_bc_missions","type":"texte","longueur":100},{"code":"coordonnees","libelle":"Coordonnées","colonne":null,"type":"json","gere":true},{"code":"rattachements","libelle":"Contacts","colonne":null,"type":"json","gere":true,"aide":"Lus par page ; seuls les contacts modifiés, ajoutés ou retirés sont enregistrés"},{"code":"nb_rattachements","libelle":"Nombre de contacts","colonne":null,"type":"nombre","gere":true,"lecture_seule":true},{"code":"liens","libelle":"Liens","colonne":null,"type":"json","gere":true},{"code":"enfants","libelle":"Niveaux inférieurs","colonne":null,"type":"json","gere":true,"lecture_seule":true}]}'::jsonb),
 ('individu', 'Individu', 'individu', 'ind_id', 'ind_proprietes', '{"libelle":"Individu","titre":"[civilite] [prenom] [nom]","sections":[{"code":"identite","titre":"Identité","groupes":[{"titre":"Identité","champs":["civilite","prenom","nom","date_naissance","pays","usage"]},{"code":"roles","titre":"Dans notre société","champs":["roles","utilisateur"],"largeur":"plein"},{"titre":"Notes","champs":["commentaire"],"largeur":"plein"}]}],"champs":[{"code":"civilite","libelle":"Civilité","colonne":"ind_civilite","type":"liste","options":[{"valeur":"M.","libelle":"M."},{"valeur":"Mme","libelle":"Mme"}]},{"code":"nom","libelle":"Nom","colonne":"ind_nom","type":"texte","obligatoire":true,"longueur":80},{"code":"prenom","libelle":"Prénom","colonne":"ind_prenom","type":"texte","longueur":80},{"code":"date_naissance","libelle":"Date de naissance","colonne":"ind_date_naissance","type":"date","confidentiel":true},{"code":"pays","libelle":"Pays","colonne":"ind_pays","type":"texte","defaut":"FR","longueur":2,"format":"regex:^[A-Za-z]{2}$"},{"code":"roles","libelle":"Rôles","colonne":"ind_roles","type":"json","aide":"Chargé d''affaires, chiffreur, salarié, intérimaire, utilisateur… : repris par les autres modules"},{"code":"utilisateur","libelle":"Identifiant de connexion","colonne":"ind_utilisateur","type":"texte","longueur":50,"non_copie":true,"aide":"Pour le futur module des droits"},{"code":"actif","libelle":"Actif","colonne":"ind_actif","type":"booleen","obligatoire":true,"defaut":true},{"code":"usage","libelle":"Utilisation","colonne":"ind_usage","type":"liste","obligatoire":true,"defaut":"A","options":[{"valeur":"A","libelle":"En service"},{"valeur":"N","libelle":"Ne plus utiliser"},{"valeur":"S","libelle":"En sommeil"}],"aide":"Ne plus utiliser : les documents en cours se terminent, plus de nouveau choix ; en sommeil : masquée par défaut dans les listes"},{"code":"commentaire","libelle":"Notes","colonne":"ind_commentaire","type":"zone"},{"code":"coordonnees","libelle":"Coordonnées","colonne":null,"type":"json","gere":true},{"code":"rattachements","libelle":"Rattachements","colonne":null,"type":"json","gere":true},{"code":"nb_rattachements","libelle":"Nombre de rattachements","colonne":null,"type":"nombre","gere":true,"lecture_seule":true},{"code":"salarie","libelle":"Salarié","colonne":null,"type":"json","gere":true,"lecture_seule":true}]}'::jsonb),
 ('projet', 'Projet', 'projet', 'prj_id', 'prj_proprietes', '{"libelle":"Projet","titre":"[code] – [libelle]","sous_titre":"[ville]","chrono":{"champ":"code","prefixe":"PRJ-","format":"{P}{AAAA}-{N:3}","raz":"A"},"sections":[{"code":"informations","titre":"Projet","groupes":[{"titre":"Identification","champs":["code","libelle","tiers_id","client_libre"]},{"titre":"Suivi commercial","champs":["statut","priorite","evaluation","date_remise","date_decision","responsable_ind_id","metreur_ind_id"]},{"titre":"Estimation","champs":["montant_estime","debut_prevu","fin_prevue","duree_estimee","duree_unite"]},{"titre":"Adresse des travaux","champs":["adresse","code_postal","ville","zone"]},{"titre":"Commentaire","champs":["commentaire","responsable"],"largeur":"plein"}]},{"code":"intervenants","titre":"Intervenants","groupes":[{"titre":"Petit annuaire","champs":["intervenants"],"largeur":"plein"}]}],"champs":[{"code":"intervenants","libelle":"Intervenants","colonne":null,"type":"json","gere":true,"largeur":"plein","aide":"Tiers et contacts de l''annuaire avec leur fonction (client, architecte, sous-traitant, payeur…)"},{"code":"code","libelle":"Code","colonne":"prj_code","type":"texte","obligatoire":true,"longueur":20,"non_copie":true},{"code":"libelle","libelle":"Libellé","colonne":"prj_libelle","type":"texte","obligatoire":true,"longueur":150,"largeur":"plein"},{"code":"tiers_id","libelle":"Client","colonne":"prj_tiers_id","type":"nombre","reference":"tiers","aide":"Client de l''annuaire ; ＋ : nouveau prospect (tiers provisoire)"},{"code":"client_libre","libelle":"Client (saisie libre)","colonne":"prj_client_libre","type":"texte","longueur":300,"largeur":"plein","aide":"Avant la création du client dans l''annuaire : nom, contact, téléphone…"},{"code":"priorite","libelle":"Priorité","colonne":"prj_priorite","type":"liste","requete":"SELECT lva_code, lva_libelle FROM liste_valeur WHERE lva_liste = ''PRIORITE_PROJET'' AND lva_actif ORDER BY lva_ordre, lva_code","aide":"Liste paramétrable (Paramètres › Référentiels communs)"},{"code":"evaluation","libelle":"Évaluation","colonne":"prj_evaluation","type":"liste","requete":"SELECT lva_code, lva_libelle FROM liste_valeur WHERE lva_liste = ''EVALUATION_PROJET'' AND lva_actif ORDER BY lva_ordre, lva_code","aide":"Chances d''obtenir le projet (liste paramétrable)"},{"code":"responsable_ind_id","libelle":"Responsable","colonne":"prj_responsable_ind_id","type":"nombre","reference":"individu_societe","aide":"Individu de notre société ou de l''une de ses agences"},{"code":"metreur_ind_id","libelle":"Métreur","colonne":"prj_metreur_ind_id","type":"nombre","reference":"individu_societe","aide":"Individu de notre société ou de l''une de ses agences"},{"code":"debut_prevu","libelle":"Début des travaux estimé","colonne":"prj_debut_prevu","type":"date"},{"code":"fin_prevue","libelle":"Fin des travaux estimée","colonne":"prj_fin_prevue","type":"date"},{"code":"duree_estimee","libelle":"Durée estimée","colonne":"prj_duree_estimee","type":"nombre","format":"99999999.9"},{"code":"duree_unite","libelle":"Unité de durée","colonne":"prj_duree_unite","type":"liste","obligatoire":true,"defaut":"H","options":[{"valeur":"H","libelle":"Heures"},{"valeur":"J","libelle":"Jours"}]},{"code":"adresse","libelle":"Adresse","colonne":"prj_adresse","type":"texte","longueur":200,"largeur":"plein"},{"code":"code_postal","libelle":"Code postal","colonne":"prj_code_postal","type":"texte","longueur":10},{"code":"zone","libelle":"Zone de déplacement","colonne":"prj_zone","type":"nombre","format":"9","aide":"Zone estimée (0 à 9), comme les zones du Pointage"},{"code":"statut","libelle":"Statut","colonne":"prj_statut","type":"liste","obligatoire":true,"defaut":"EN_COURS","options":[{"valeur":"EN_COURS","libelle":"En cours de chiffrage"},{"valeur":"REMIS","libelle":"Offre remise"},{"valeur":"OBTENU","libelle":"Obtenu"},{"valeur":"PERDU","libelle":"Perdu"},{"valeur":"ABANDONNE","libelle":"Abandonné"}],"aide":"Obtenu : propose d''ouvrir le chantier"},{"code":"date_remise","libelle":"Date de remise","colonne":"prj_date_remise","type":"date"},{"code":"date_decision","libelle":"Date de décision","colonne":"prj_date_decision","type":"date"},{"code":"montant_estime","libelle":"Montant estimé HT","colonne":"prj_montant_estime","type":"nombre","format":"999999999999.99"},{"code":"responsable","libelle":"Responsable (ancienne saisie)","colonne":"prj_responsable","type":"texte","longueur":100,"lecture_seule":true,"aide":"Texte d''avant le lot 6 : choisir le responsable dans la liste des individus"},{"code":"ville","libelle":"Ville","colonne":"prj_ville","type":"texte","longueur":100},{"code":"commentaire","libelle":"Commentaire","colonne":"prj_commentaire","type":"zone"}]}'::jsonb),
 ('affaire', 'Affaire', 'affaire', 'aff_id', 'aff_proprietes', '{"libelle":"Affaire","titre":"[code] – [libelle]","sous_titre":"[responsable]","chrono":{"champ":"code","prefixe":"AFF-","format":"{P}{AAAA}-{N:3}","raz":"A"},"sections":[{"code":"informations","titre":"Affaire","groupes":[{"titre":"Identification","champs":["code","libelle","nature","tiers_id"]},{"titre":"Suivi","champs":["statut","date_ouverture","date_cloture","responsable"]},{"titre":"Commentaire","champs":["commentaire"],"largeur":"plein"}]},{"code":"intervenants","titre":"Intervenants","groupes":[{"titre":"Petit annuaire","champs":["intervenants"],"largeur":"plein"}]}],"champs":[{"code":"intervenants","libelle":"Intervenants","colonne":null,"type":"json","gere":true,"largeur":"plein","aide":"Tiers et contacts de l''annuaire avec leur fonction (client, architecte, sous-traitant, payeur…)"},{"code":"code","libelle":"Code","colonne":"aff_code","type":"texte","obligatoire":true,"longueur":20,"non_copie":true},{"code":"libelle","libelle":"Libellé","colonne":"aff_libelle","type":"texte","obligatoire":true,"longueur":150,"largeur":"plein"},{"code":"nature","libelle":"Nature","colonne":"aff_nature","type":"liste","obligatoire":true,"defaut":"C","options":[{"valeur":"C","libelle":"Regroupement de chantiers"},{"valeur":"G","libelle":"Gestion (frais hors chantier)"}]},{"code":"tiers_id","libelle":"Client","colonne":"aff_tiers_id","type":"nombre","reference":"tiers"},{"code":"statut","libelle":"Statut","colonne":"aff_statut","type":"liste","obligatoire":true,"defaut":"OUVERTE","options":[{"valeur":"OUVERTE","libelle":"Ouverte"},{"valeur":"CLOSE","libelle":"Close"}]},{"code":"date_ouverture","libelle":"Ouverture","colonne":"aff_date_ouverture","type":"date"},{"code":"date_cloture","libelle":"Clôture","colonne":"aff_date_cloture","type":"date"},{"code":"responsable","libelle":"Responsable","colonne":"aff_responsable","type":"texte","longueur":100},{"code":"commentaire","libelle":"Commentaire","colonne":"aff_commentaire","type":"zone"}]}'::jsonb),
 ('chantier', 'Chantier', 'chantier', 'cha_id', 'cha_proprietes', '{"libelle":"Chantier","titre":"[code] – [libelle]","sous_titre":"[ville]","chrono":{"champ":"code","prefixe":"CH-","format":"{P}{AAAA}-{N:3}","raz":"A"},"sections":[{"code":"informations","titre":"Chantier","groupes":[{"titre":"Identification","champs":["code","libelle","aff_id","prj_id","tiers_id"]},{"titre":"Adresse","champs":["adresse","code_postal","ville","contact_ind_id"]},{"titre":"Suivi","champs":["statut","date_ouverture","code_analytique"]},{"titre":"Travaux","champs":["debut_prevu","date_fin_prevue","debut_reel","fin_reelle"]},{"titre":"Équipe","champs":["charge_ind_id","conducteur_ind_id","chef_ind_id"]},{"titre":"Stock","champs":["depot","stock_tenu"]},{"titre":"Commentaire","champs":["commentaire"],"largeur":"plein"}]},{"code":"intervenants","titre":"Intervenants","groupes":[{"titre":"Petit annuaire","champs":["intervenants"],"largeur":"plein"}]}],"champs":[{"code":"intervenants","libelle":"Intervenants","colonne":null,"type":"json","gere":true,"largeur":"plein","aide":"Tiers et contacts de l''annuaire avec leur fonction (client, architecte, sous-traitant, payeur…)"},{"code":"code","libelle":"Code","colonne":"cha_code","type":"texte","obligatoire":true,"longueur":20,"non_copie":true},{"code":"libelle","libelle":"Libellé","colonne":"cha_libelle","type":"texte","obligatoire":true,"longueur":150,"largeur":"plein"},{"code":"aff_id","libelle":"Affaire","colonne":"cha_aff_id","type":"nombre","reference":"affaire","aide":"Affaire qui regroupe ce chantier"},{"code":"prj_id","libelle":"Projet","colonne":"cha_prj_id","type":"nombre","reference":"projet","aide":"Projet obtenu à l''origine du chantier"},{"code":"tiers_id","libelle":"Client","colonne":"cha_tiers_id","type":"nombre","reference":"tiers"},{"code":"adresse","libelle":"Adresse","colonne":"cha_adresse","type":"texte","longueur":200,"largeur":"plein"},{"code":"code_postal","libelle":"Code postal","colonne":"cha_code_postal","type":"texte","longueur":10},{"code":"ville","libelle":"Ville","colonne":"cha_ville","type":"texte","longueur":100},{"code":"contact_ind_id","libelle":"Contact sur place","colonne":"cha_contact_ind_id","type":"nombre","reference":"individu","aide":"Le client ou un salarié : repris dans l''adresse des travaux et de livraison des documents"},{"code":"statut","libelle":"Statut","colonne":"cha_statut","type":"liste","obligatoire":true,"defaut":"OUVERT","options":[{"valeur":"OUVERT","libelle":"Ouvert"},{"valeur":"TERMINE","libelle":"Terminé"},{"valeur":"CLOS","libelle":"Clos"}]},{"code":"date_ouverture","libelle":"Ouverture","colonne":"cha_date_ouverture","type":"date"},{"code":"date_fin_prevue","libelle":"Fin des travaux prévue","colonne":"cha_date_fin_prevue","type":"date"},{"code":"conducteur_ind_id","libelle":"Conducteur de travaux","colonne":"cha_conducteur_ind_id","type":"nombre","reference":"individu_societe","aide":"Individu de notre société ou de l''une de ses agences (annuaire)"},{"code":"charge_ind_id","libelle":"Chargé d''affaires","colonne":"cha_charge_ind_id","type":"nombre","reference":"individu_societe","aide":"Individu de notre société ou de l''une de ses agences"},{"code":"chef_ind_id","libelle":"Chef d''équipe","colonne":"cha_chef_ind_id","type":"nombre","reference":"individu_societe","aide":"Individu de notre société ou de l''une de ses agences"},{"code":"code_analytique","libelle":"Code analytique","colonne":"cha_code_analytique","type":"texte","longueur":30,"aide":"Section analytique de l''export comptable (vide : code du chantier)"},{"code":"debut_prevu","libelle":"Début des travaux prévu","colonne":"cha_debut_prevu","type":"date"},{"code":"debut_reel","libelle":"Début réel","colonne":"cha_debut_reel","type":"date"},{"code":"fin_reelle","libelle":"Fin réelle","colonne":"cha_fin_reelle","type":"date"},{"code":"depot","libelle":"Dépôt de stock","colonne":"cha_depot","type":"booleen","defaut":false,"aide":"Module Stock : dépôt géré (emplacements, inventaires, mini 