 ('marche', 'Marché', 'marche', 'mar_id', 'mar_proprietes', '{"libelle":"Marché","titre":"[code] – [libelle]","sous_titre":"","chrono":{"champ":"code","prefixe":"M-","format":"{P}{PARENT}-{N}","raz":"J","parent":"cha_id","variante":"sens","variantes":[{"valeur":"V","libelle":"Vente","prefixe":"M-"},{"valeur":"ST","libelle":"Sous-traitance","prefixe":"MST-"}]},"sections":[{"code":"informations","titre":"Marché","groupes":[{"titre":"Identification","champs":["code","libelle","sens","cha_id","tiers_id","ent_id"]},{"titre":"Conditions","champs":["nature","montant_ht","depassement_autorise","retenue_pct","date","date_reception","reserves","reserves_levees_le","statut"]},{"titre":"Sous-traitance","champs":["marche_vente_id","garantie","montant_agree","autoliquidation","debut_contractuel","fin_contractuelle"]},{"titre":"Commentaire","champs":["commentaire"],"largeur":"plein"}]},{"code":"intervenants","titre":"Intervenants","groupes":[{"titre":"Petit annuaire","champs":["intervenants"],"largeur":"plein"}]}],"champs":[{"code":"intervenants","libelle":"Intervenants","colonne":null,"type":"json","gere":true,"largeur":"plein","aide":"Tiers et contacts de l''annuaire avec leur fonction (client, architecte, sous-traitant, payeur…)"},{"code":"code","libelle":"Code","colonne":"mar_code","type":"texte","obligatoire":true,"longueur":20,"non_copie":true},{"code":"libelle","libelle":"Libellé","colonne":"mar_libelle","type":"texte","obligatoire":true,"longueur":150,"largeur":"plein"},{"code":"cha_id","libelle":"Chantier","colonne":"mar_cha_id","type":"nombre","obligatoire":true,"reference":"chantier"},{"code":"sens","libelle":"Sens","colonne":"mar_sens","type":"liste","defaut":"V","options":[{"valeur":"V","libelle":"Vente (client)"},{"valeur":"ST","libelle":"Sous-traitance"}],"aide":"Marché de vente au client ou marché de sous-traitance (un par axe de facturation du sous-traitant)"},{"code":"tiers_id","libelle":"Client ou sous-traitant","colonne":"mar_tiers_id","type":"nombre","reference":"tiers"},{"code":"ent_id","libelle":"Commande de base","colonne":"mar_ent_id","type":"nombre","reference":"commande","aide":"Commande dont la validation a ouvert le marché"},{"code":"marche_vente_id","libelle":"Marché de vente lié","colonne":"mar_marche_vente_id","type":"nombre","reference":"marche","aide":"Facultatif : marché du client sur lequel porte la sous-traitance (intervenant, paiement direct)"},{"code":"garantie","libelle":"Garantie de paiement","colonne":"mar_garantie","type":"liste","options":[{"valeur":"PAIEMENT_DIRECT","libelle":"Paiement direct (public)"},{"valeur":"DELEGATION","libelle":"Délégation de paiement (privé)"},{"valeur":"CAUTION","libelle":"Caution (privé)"},{"valeur":"AUCUNE","libelle":"Aucune"}]},{"code":"montant_agree","libelle":"Montant agréé (DC4)","colonne":"mar_montant_agree","type":"nombre","format":"999999999999.99","aide":"Plafond du paiement direct agréé par le maître d''ouvrage"},{"code":"autoliquidation","libelle":"Autoliquidation de la TVA","colonne":"mar_autoliquidation","type":"booleen","defaut":true,"aide":"Travaux de construction sous-traités : le sous-traitant facture HT"},{"code":"debut_contractuel","libelle":"Début contractuel","colonne":"mar_debut_contractuel","type":"date"},{"code":"fin_contractuelle","libelle":"Fin contractuelle","colonne":"mar_fin_contractuelle","type":"date","aide":"Délai d''exécution du sous-traitant (jalon du planning)"},{"code":"nature","libelle":"Nature","colonne":"mar_nature","type":"liste","obligatoire":true,"defaut":"P","options":[{"valeur":"P","libelle":"Marché privé"},{"valeur":"U","libelle":"Marché public"}]},{"code":"montant_ht","libelle":"Montant HT","colonne":"mar_montant_ht","type":"nombre","format":"999999999999.99","lecture_seule":true,"aide":"Calculé : total des commandes validées du marché (commande de base et avenants)"},{"code":"depassement_autorise","libelle":"Dépassement autorisé","colonne":"mar_depassement_autorise","type":"booleen","defaut":false,"aide":"L''avancement peut dépasser le montant du marché (travaux publics : quantités réelles)"},{"code":"retenue_pct","libelle":"Retenue de garantie (%)","colonne":"mar_retenue_pct","type":"nombre","format":"999.99","aide":"% du TTC de chaque facture du marché (5 % au plus), poste du pied global et échéance à part"},{"code":"date","libelle":"Date","colonne":"mar_date","type":"date","obligatoire":true},{"code":"date_reception","libelle":"Date de réception","colonne":"mar_date_reception","type":"date","aide":"Réception des travaux : la retenue de garantie est libérée un an après, sauf réserves"},{"code":"reserves","libelle":"Réception avec réserves","colonne":"mar_reserves","type":"booleen","obligatoire":true,"defaut":false,"aide":"Réserves non levées : la retenue de garantie reste bloquée"},{"code":"reserves_levees_le","libelle":"Réserves levées le","colonne":"mar_reserves_levees_le","type":"date","aide":"Levée après l''échéance : la retenue est libérée à la levée"},{"code":"statut","libelle":"Statut","colonne":"mar_statut","type":"liste","obligatoire":true,"defaut":"EN_COURS","options":[{"valeur":"EN_COURS","libelle":"En cours"},{"valeur":"SOLDE","libelle":"Soldé"},{"valeur":"RESILIE","libelle":"Résilié"}]},{"code":"commentaire","libelle":"Commentaire","colonne":"mar_commentaire","type":"zone"}]}'::jsonb)
